class Permissions:
    def __init__(self):
        self.permissions = {
            'viewer': ['read'],
            'editor': ['read', 'write']
        }

    def allowed(self, role, action):
        if role not in self.permissions:
            return False
        return action in self.permissions[role]

    def grant(self, role, action):
        if role not in self.permissions:
            self.permissions[role] = []
        if action not in self.permissions[role]:
            self.permissions[role].append(action)
